cypress_script:
describe('Shopping Cart Functionality', () => {
  it('should display the shopping cart with items', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.url().should('include', '/cart.html');
    cy.get('[data-test="secondary-header"]').should('be.visible');
    cy.get('[data-test="cart-contents-container"]').should('be.visible');
    cy.get('[data-test="checkout"]').should('be.visible');
    cy.get('[data-test="continue-shopping"]').should('be.visible');
  });
  it('should allow the user to continue shopping', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.get('[data-test="continue-shopping"]').click();
    cy.url().should('include', '/inventory.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Shopping Cart Functionality', () => {
  test('should display the shopping cart with items', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await expect(page).toHaveURL(/.*cart.html/);
    await expect(page.locator('[data-test="secondary-header"]')).toBeVisible();
    await expect(page.locator('[data-test="cart-contents-container"]')).toBeVisible();
    await expect(page.locator('[data-test="checkout"]')).toBeVisible();
    await expect(page.locator('[data-test="continue-shopping"]')).toBeVisible();
  });
  test('should allow the user to continue shopping', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await page.click('[data-test="continue-shopping"]');
    await expect(page).toHaveURL(/.*inventory.html/);
  });
});
